    ('b0000000-0000-4000-8000-000000000009'::uuid, 'โรงอาหารกลาง มก.กำแพงแสน ต.กำแพงแสน อ.กำแพงแสน จ.นครปฐม', '06:30–14:00 จันทร์–ศุกร์', 14.023580, 99.968920),
    ('b0000000-0000-4000-8000-000000000010'::uuid, '77 ม.4 ต.ห้วยขวาง อ.กำแพงแสน จ.นครปฐม', '08:00–18:00 ปิดวันอังคาร', 14.031240, 99.993170),
    ('b0000000-0000-4000-8000-000000000011'::uuid, '18 ซ.พหลโยธิน 45 แขวงลาดยาว เขตจตุจักร กรุงเทพฯ', '06:00–21:00 ทุกวัน', 13.846930, 100.568420),
    ('b0000000-0000-4000-8000-000000000012'::uuid, 'ตรงข้ามประตู 2 มก.กำแพงแสน ต.กำแพงแสน อ.กำแพงแสน จ.นครปฐม', '09:00–20:00 ทุกวัน', 14.025310, 99.975460)
